package com.worklyn.modules.payroll.service;
import com.worklyn.modules.attendance.model.*;import com.worklyn.modules.attendance.service.AttendanceService;import com.worklyn.modules.integration.*;import com.worklyn.modules.leave.model.*;import com.worklyn.modules.leave.service.LeaveService;import com.worklyn.modules.payroll.dto.*;import com.worklyn.modules.payroll.model.*;import com.worklyn.modules.payroll.repository.PayrollRepository;
import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.math.*;import java.time.*;import java.time.temporal.*;import java.util.*;import java.util.concurrent.TimeUnit;
@Service public class PayrollService {
 private final PayrollRepository payroll;private final EmployeeDirectory employees;private final AttendanceService attendance;private final LeaveService leaves;private final WorkflowRecoveryPort rewind;private final Optional<StringRedisTemplate> redis;
 public PayrollService(PayrollRepository p,EmployeeDirectory e,AttendanceService a,LeaveService l,WorkflowRecoveryPort w,org.springframework.beans.factory.ObjectProvider<StringRedisTemplate> r){payroll=p;employees=e;attendance=a;leaves=l;rewind=w;redis=Optional.ofNullable(r.getIfAvailable());}
 public PayrollProcessResult process(String period,String actorId,String key){YearMonth ym=parse(period);if(actorId==null||actorId.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Processor identity is required");if(key==null||key.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Idempotency-Key is required");if(payroll.existsByPayrollPeriodAndStatus(period,PayrollStatus.FINALIZED))throw new ResponseStatusException(HttpStatus.CONFLICT,"Payroll period is finalized");String redisKey="worklyn:payroll:idempotency:"+period+":"+key;try{if(redis.isPresent()){String prior=redis.get().opsForValue().get(redisKey);if(prior!=null){List<PayrollResponse> existing=payroll.findByPayrollPeriod(period).stream().map(PayrollResponse::from).toList();return new PayrollProcessResult(period,existing.size(),existing,true);}}}catch(RuntimeException ignored){/* Redis is an optimization; Mongo remains authoritative. */}
  LocalDate first=ym.atDay(1),last=ym.atEndOfMonth();int working=(int)first.datesUntil(last.plusDays(1)).filter(d->d.getDayOfWeek().getValue()<6).count();List<PayrollResponse> result=new ArrayList<>();try{for(EmployeeSnapshot emp:employees.findActiveEmployees()){if(emp.baseSalary()==null||emp.baseSalary().signum()<0)continue;Optional<PayrollRecord> old=payroll.findByEmployeeIdAndPayrollPeriod(emp.id(),period);if(old.isPresent()&&old.get().getStatus()==PayrollStatus.FINALIZED)continue;if(old.isPresent()&&old.get().getStatus()==PayrollStatus.PROCESSED){result.add(PayrollResponse.from(old.get()));continue;}
    List<Attendance> attend=attendance.forPeriod(emp.id(),first,last);int present=(int)attend.stream().filter(x->x.getStatus()==AttendanceStatus.PRESENT||x.getStatus()==AttendanceStatus.LATE).count();int half=(int)attend.stream().filter(x->x.getStatus()==AttendanceStatus.HALF_DAY).count();int paidLeave=0,unpaidLeave=0;for(LeaveRequest leave:leaves.approvedForPeriod(emp.id(),first,last)){int days=businessDays(max(first,leave.getStartDate()),min(last,leave.getEndDate()));if(leave.getLeaveType()==LeaveType.UNPAID)unpaidLeave+=days;else paidLeave+=days;}
    unpaidLeave=Math.max(unpaidLeave, Math.max(0, working-present-half-paidLeave));BigDecimal daily=working==0?BigDecimal.ZERO:emp.baseSalary().divide(BigDecimal.valueOf(working),8,RoundingMode.HALF_UP);BigDecimal payableDays=BigDecimal.valueOf(present).add(BigDecimal.valueOf(half).multiply(new BigDecimal("0.5"))).add(BigDecimal.valueOf(paidLeave));BigDecimal gross=daily.multiply(payableDays).setScale(2,RoundingMode.HALF_UP);BigDecimal tax=taxFor(gross);PayrollRecord r=old.orElseGet(PayrollRecord::new);r.setEmployeeId(emp.id());r.setPayrollPeriod(period);r.setBaseSalary(emp.baseSalary());r.setWorkingDays(working);r.setPresentDays(present+half);r.setPaidLeaveDays(paidLeave);r.setUnpaidLeaveDays(unpaidLeave);r.setGrossPay(gross);r.setTaxDeduction(tax);r.setNetPay(gross.subtract(tax).max(BigDecimal.ZERO).setScale(2,RoundingMode.HALF_UP));r.setStatus(PayrollStatus.PROCESSED);r.setProcessedAt(Instant.now());r.setProcessedBy(actorId);r.setIdempotencyKey(key);result.add(PayrollResponse.from(payroll.save(r)));}
   try{redis.ifPresent(t->{try{t.opsForValue().set(redisKey,"DONE",24,TimeUnit.HOURS);}catch(RuntimeException ignored){}});}catch(RuntimeException ignored){}return new PayrollProcessResult(period,result.size(),List.copyOf(result),false);
  }catch(RuntimeException ex){rewind.recordPayrollFailure(period,key,ex.getMessage()==null?ex.getClass().getSimpleName():ex.getMessage(),Map.of("actorId",actorId));throw ex;}}
 public List<PayrollResponse> period(String period){parse(period);return payroll.findByPayrollPeriod(period).stream().map(PayrollResponse::from).toList();}
 public PayrollResponse payslip(String employeeId,String period,ActorContext actor){parse(period);if(!actor.isHrOrAdmin()&&!Objects.equals(employeeId,actor.employeeId()))throw new org.springframework.security.access.AccessDeniedException("Cannot view another employee's payslip");return payroll.findByEmployeeIdAndPayrollPeriod(employeeId,period).map(PayrollResponse::from).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Payslip not found"));}
 public void finalizePeriod(String period,ActorContext actor){parse(period);if(!actor.isHrOrAdmin())throw new org.springframework.security.access.AccessDeniedException("Only HR/ADMIN can finalize payroll");List<PayrollRecord> records=payroll.findByPayrollPeriod(period);if(records.isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"No payroll records exist for this period");if(records.stream().anyMatch(r->r.getStatus()!=PayrollStatus.PROCESSED))throw new ResponseStatusException(HttpStatus.CONFLICT,"All payroll records must be PROCESSED and not already finalized");records.forEach(r->r.setStatus(PayrollStatus.FINALIZED));payroll.saveAll(records);}
 private YearMonth parse(String p){try{if(p==null||!p.matches("^\\d{4}-(0[1-9]|1[0-2])$"))throw new DateTimeException("bad format");return YearMonth.parse(p);}catch(DateTimeException ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Period must use YYYY-MM format",ex);}}
 private BigDecimal taxFor(BigDecimal gross){if(gross.compareTo(new BigDecimal("100000"))<=0)return BigDecimal.ZERO.setScale(2);if(gross.compareTo(new BigDecimal("200000"))<=0)return gross.subtract(new BigDecimal("100000")).multiply(new BigDecimal("0.05")).setScale(2,RoundingMode.HALF_UP);return new BigDecimal("5000").add(gross.subtract(new BigDecimal("200000")).multiply(new BigDecimal("0.10"))).setScale(2,RoundingMode.HALF_UP);}
 private int businessDays(LocalDate s,LocalDate e){if(s.isAfter(e))return 0;return (int)s.datesUntil(e.plusDays(1)).filter(d->d.getDayOfWeek().getValue()<6).count();}private LocalDate max(LocalDate a,LocalDate b){return a.isAfter(b)?a:b;}private LocalDate min(LocalDate a,LocalDate b){return a.isBefore(b)?a:b;}
}
